catalog_script_client.script:
function onLoad() {
    alert('onLoad function called'); // Pop-up-Nachricht

    var ga = new GlideAjax('InvoiceDateHelfer');
    ga.addParam('sysparm_name', 'getAvailableYearsAndMonths');
    ga.addParam('userName', g_user.userName); // Hier setzen wir den Benutzernamen des eingeloggten Users

    alert('Making GlideAjax call'); // Pop-up-Nachricht

    ga.getXMLAnswer(function(response) {
        alert('Received response: ' + response); // Pop-up-Nachricht

        try {
            var result = JSON.parse(response);
            alert('Parsed result: ' + JSON.stringify(result)); // Pop-up-Nachricht

            // Jahr Dropdown aktualisieren
            var yearDropdown = g_form.getControl('which_year');
            if (yearDropdown) {
                alert('Year dropdown found'); // Pop-up-Nachricht
                yearDropdown.options.length = 0; // Clear existing options
                result.years.forEach(function(year) {
                    alert('Adding year option: ' + year); // Debugging-Ausgabe
                    var option = new Option(year, year);
                    yearDropdown.add(option);
                });
                alert('Year dropdown updated with options: ' + JSON.stringify(result.years)); // Pop-up-Nachricht
            } else {
                alert('Year dropdown not found'); // Pop-up-Nachricht
            }

            // Monat Dropdown aktualisieren
            var monthDropdown = g_form.getControl('month_of_the_invoice');
            if (monthDropdown) {
                alert('Month dropdown found'); // Pop-up-Nachricht
                monthDropdown.options.length = 0; // Clear existing options
                result.months.forEach(function(month) {
                    alert('Adding month option: ' + month); // Debugging-Ausgabe
                    var option = new Option(month, month);
                    monthDropdown.add(option);
                });
                alert('Month dropdown updated with options: ' + JSON.stringify(result.months)); // Pop-up-Nachricht
            } else {
                alert('Month dropdown not found'); // Pop-up-Nachricht
            }
        } catch (e) {
            alert('Error parsing JSON response: ' + e.message); // Pop-up-Nachricht
        }
    });

    alert('GlideAjax call made'); // Pop-up-Nachricht
}
